// Material SourceTrafficComposite (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_propsSize: vec2f,
  p_trafficSize: vec2f,
  p_propsFiltered: f32,
  p_trafficFiltered: f32,
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_propsAtlas: texture_2d<f32>;
@group(2) @binding(2) var tex_trafficAtlas: texture_2d<f32>;
@group(2) @binding(3) var material_sampler: sampler;

fn traffic_composite_texel(props: texture_2d<f32>, propsSampler: sampler,
  traffic: texture_2d<f32>, trafficSampler: sampler, coord: vec2f, kind: f32,
  propsSize: vec2f, trafficSize: vec2f, propsFiltered: f32, trafficFiltered: f32) -> vec4f {
  if (kind > 0.5) {
    let point = (floor(coord * trafficSize) + vec2f(0.5)) / trafficSize;
    return textureSampleLevel(traffic, trafficSampler, mix(point, coord, trafficFiltered), 0.0);
  }
  let point = (floor(coord * propsSize) + vec2f(0.5)) / propsSize;
  return textureSampleLevel(props, propsSampler, mix(point, coord, propsFiltered), 0.0);
}
const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: f32 = in.uv1.x;
  let v1: vec4f = traffic_composite_texel(tex_propsAtlas, material_sampler, tex_trafficAtlas, material_sampler, in.uv, v0, material.p_propsSize, material.p_trafficSize, material.p_propsFiltered, material.p_trafficFiltered);
  let v2: vec3f = v1.xyz;
  let v3: f32 = v1.w;
  out.base_color = v2;
  out.alpha = v3;
  return out;
}
